function progress(ts){ts=[...ts].sort((a,b)=>S.order==='created'?tsTime(b.created)-tsTime(a.created):S.order==='due'?(tsTime(a.due)||Infinity)-(tsTime(b.due)||Infinity):rank(a)-rank(b));const attention=ts.filter(t=>['wait_user','error'].includes(t.status)&&(!t.deferUntil||tsTime(t.deferUntil)<now().getTime())).sort((a,b)=>(a.status==='error'?-1:0)-(b.status==='error'?-1:0));return `<div class="filters">${[['priority','重点优先'],['due','按需用时间'],['created','按交代时间']].map(([k,l])=>`<button class="${(S.order||'priority')===k?'active':''}" onclick="S.order='${k}';save();render()">${l}</button>`).join('')}</div>${attention.length&&S.filter==='all'?`<div class="sectionlabel">先看这几件</div>${attention.slice(0,2).map((t,i)=>`<button class="focus-row" onclick="detail('${t.id}')"><span class="n">0${i+1}</span><span class="grow"><strong>${esc(t.title)}</strong><p>${esc(describe(t))}</p></span>${badge(t)}</button>`).join('')}`:''}${S.topics.map(theme=>{const list=ts.filter(t=>t.theme===theme);if(!list.length)return '';const ongoing=list.filter(t=>t.kind==='continuing'),once=list.filter(t=>t.kind!=='continuing');return `<section><div class="topic-head"><h2>${esc(theme)}</h2><span>${list.length} 件 · ${list.filter(t=>statusGroup(t)==='you').length} 件需要你</span></div>${ongoing.length?`<div class="continuing-label">持续照看 · 主体常驻</div>${ongoing.map(t=>card(t)).join('')}`:''}${once.slice(0,2).map(t=>card(t)).join('')}${once.length>2?`<details><summary class="quietmore">其余 ${once.length-2} 件，展开看</summary>${once.slice(2).map(t=>card(t)).join('')}</details>`:''}</section>`}).join('')}${ts.length?'':'<p class="muted small">这个筛选下暂时没有任务。</p>'}`}
const tsTime=ts;function rank(t){return {error:0,wait_user:1,running:2,todo:3,paused:4,done:5,cancelled:6}[t.status]}
function setTheme(n){S.themeFilter=n;save();render()}
function timelineDates(){const d=new Date(now().toLocaleString('en-US',{timeZone:'Asia/Shanghai'}));const today=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');let start=Date.parse(today+'T12:00:00Z'),len=1;if(S.range==='three'){start-=86400000;len=3}else if(S.range==='week'){start-=3*86400000;len=7}else if(S.range==='all'){const dates=[...S.items.filter(t=>t.kind!=='continuing'),...S.instances].filter(t=>t.due).map(t=>new Date(ts(t.due)+8*3600000).toISOString().slice(0,10)).sort();start=Date.parse((dates[0]||today)+'T12:00:00Z');len=Math.ceil((Date.parse((dates.at(-1)||today)+'T12:00:00Z')-start)/86400000)+1}return Array.from({length:Math.min(len,60)},(_,i)=>new Date(start+i*86400000).toISOString().slice(0,10))}
function dateOf(t){return t.due?new Date(ts(t.due)+8*3600000).toISOString().slice(0,10):null}
function part(t){if(!t.due)return -1;const h=new Date(ts(t.due)+8*3600000).getUTCHours();return h<12?0:h<18?1:2}
function timelineEntries(ts){const ids=new Set(ts.map(t=>t.id));return [...new Map([...ts.filter(t=>t.kind!=='continuing'),...S.instances.filter(x=>ids.has(x.parent)&&(S.showArchived?x.archive==='archived':x.archive!=='archived'))].map(t=>[t.id,t])).values()]}
function timeline(list){const dates=timelineDates(),events=timelineEntries(list),compact=dates.length>3;let html=`<div class="timehead">时段</div>${dates.map(d=>`<div class="timehead">${d.slice(5,7)}月<strong>${d.slice(-2)}</strong></div>`).join('')}`;['上午','下午','晚上'].forEach((label,p)=>{html+=`<div class="daypart">${label}</div>`;dates.forEach(d=>{const slots=events.filter(t=>dateOf(t)===d&&part(t)===p);html+=compact?`<button class="timecell compact" onclick="slot('${d}',${p})" aria-label="${d}${label}${slots.length}项">${slots.length||'·'}${slots.length?`<small>${slots.some(x=>x.status==='wait_user')?'含等你事项':'点开查看'}</small>`:''}</button>`:`<div class="timecell">${slots.map(t=>`<button class="timeitem ${t.status}" onclick="detail('${t.id}')"><small>${fmt(t.due).slice(-5)}${t.person?' '+icon('person'):''}</small><strong>${esc(t.title.slice(0,10))}</strong><small>${STATUS[t.status]}${t.parent?' · 实例':''}</small></button>`).join('')||'<span class="muted small">—</span>'}</div>`})});return `<div class="date-range">${[['all','全部'],['today','今天'],['three','近三天'],['week','近一周']].map(([k,l])=>`<button class="${S.range===k?'active':''}" onclick="S.range='${k}';save();render()">${l}</button>`).join('')}</div><p class="clocknote">${dates[0]} — ${dates.at(-1)} · 近三天为昨天、今天、明天</p><div class="timepanel"><div class="timebar"><span>横向日期 · 纵向时段</span><span><button onclick="zoom(-1)" aria-label="缩小时间轴">−</button><button onclick="zoom(1)" aria-label="放大时间轴">＋</button></span></div><div class="timegrid" style="--n:${dates.length}">${html}</div></div><p class="clocknote">延续性主体不重复铺进时间轴，只展示本次／最近的下一次实例。${compact?'点击数字查看详情。':''}</p><details><summary class="quietmore">时间待明确 · ${events.filter(t=>!t.due).length} 项</summary>${events.filter(t=>!t.due).map(t=>card(t)).join('')}</details><div class="continuing-label">仍在持续照看</div>${list.filter(t=>t.kind==='continuing').map(t=>card(t)).join('')}`}
function slot(date,p){sheet(date+' · '+['上午','下午','晚上'][p],timelineEntries(filtered()).filter(t=>dateOf(t)===date&&part(t)===p).map(t=>card(t)).join('')||'<p class="muted">暂无安排。</p>')}
function zoom(dir){const a=['today','three','week','all'];S.range=a[Math.max(0,Math.min(3,a.indexOf(S.range)-dir))];save();render()}
function suggestion(){if(S.proposal==='declined')return '';if(S.proposal==='accepted')return `<div class="suggest"><span class="source">✧ 主动服务 · 已获确认</span><h3>辅食推荐，已经接着办。</h3><p>先确认月龄和过敏情况，再准备适龄资料。</p><button class="secondary" onclick="detail('food')">查看任务</button></div>`;return `<div class="suggest"><div class="eyebrow">我多想到的一件事 · 情景建议</div><h3>辅食灵感，要不要我也帮你找找？</h3><p>如果你在准备辅食，我可以根据月龄和过敏情况整理推荐。你同意后再创建任务，当前不计入总数。</p><button class="primary" onclick="acceptSuggestion()">好，帮我整理</button><button onclick="S.proposal='declined';save();render()">暂时不用</button></div>`}
function acceptSuggestion(){if(S.proposal==='accepted')return;S.proposal='accepted';S.items.push({id:'food',title:'小包的辅食灵感',theme:'小包成长',kind:'oneoff',status:'wait_user',person:false,source:'ai',consent:now().toISOString(),created:now().toISOString(),quote:'好，帮我整理辅食推荐。',summary:'已接下推荐整理，先请你补充月龄与过敏情况，再筛选适龄资料。',steps:[]});S.messages.push({kind:'reply',input:'好，帮我整理辅食推荐。',text:'已根据你的同意新建任务。先确认月龄和过敏信息，再给你整理合适的推荐。',ids:['food']});save();render();toast('主动建议已获确认，已加入任务。')}
function markDone(id){const t=entity(id);if(!t||!t.person||t.status!=='wait_user')return;completion(t,'user');save();closeModal();render();toast('已记录你确认完成，结果先保留在待归档。')}
function completeDemo(id){const t=entity(id);if(!t||t.status!=='running')return;completion(t,'demo');save();closeModal();render();toast('本次演示完成，延续性主体仍保持运行。')}
function later(id){entity(id).deferUntil=new Date(now().getTime()+86400000).toISOString();save();render();toast('先不打扰你，任务仍保留，明天再重点提醒。')}
function cancelAsk(id){sheet('取消这件事？',`<p>「${esc(entity(id).title)}」会停止后续推进，记录先放入待归档。</p><div class="card-actions"><button class="secondary" onclick="detail('${id}')">保留</button><button class="primary" onclick="cancelTask('${id}')">确认取消</button></div>`)}
function reopen(id){const t=entity(id);t.status=t.kind==='continuing'?'running':t.person?'wait_user':'todo';t.archive=null;t.closeReason=null;t.waitSince=t.person?now().toISOString():null;t.summary='已重新打开并保留原记录，接下来继续跟进。';S.messages=S.messages.filter(m=>!(m.kind==='result'&&m.id===id));save();closeModal();render();toast('已重新打开，自动关闭计时重新开始。')}
function restore(id){entity(id).archive='pending';save();render();detail(id)}
function recover(id){sheet('需要重新连接邮箱',`<p class="muted">邮件访问授权已失效，当前未读取会议邮件。</p><p class="small muted">真实接入时这里进入授权页。本原型只演示恢复后的状态。</p><button class="primary wide" onclick="recoverDemo('${id}')">演示重新连接成功</button>`)}
function archiveReview(){archiveSelection=pending().map(t=>t.id);drawArchive()}
function drawArchive(){sheet('这些事，要一起收好吗？',`<p class="small muted">完成／取消后先暂存。确认归档只收起记录，不删除原始对话与附件。</p>${pending().map(t=>`<label class="archive-item"><input type="checkbox" ${archiveSelection.includes(t.id)?'checked':''} onchange="toggleArchive('${t.id}',this.checked)"><span class="grow"><strong>${esc(t.title)}</strong><small>${STATUS[t.status]}${t.parent?' · 本次实例':''}${t.closeReason==='auto'?' · 自动关闭，实际完成未核实':''}</small></span></label>`).join('')||'<p class="muted">没有待归档事项。</p>'}<div class="inline-notice">自动关闭的事项会保留“未核实”标记。拿不准的可以先不归档。</div><button class="primary wide" onclick="archiveCommit()">确认归档所选事项</button>`)}
function toggleArchive(id,on){archiveSelection=on?[...new Set([...archiveSelection,id])]:archiveSelection.filter(x=>x!==id)}
function archiveCommit(){const selected=archiveSelection.map(entity).filter(t=>t&&terminal(t.status)&&t.archive==='pending');if(!selected.length)return toast('请选择需要归档的事项。');selected.forEach(t=>t.archive='archived');S.messages.push({kind:'archive',text:'已按你的确认归档 '+selected.length+' 项，历史记录、原话和附件仍可查看。'});save();closeModal();render();toast('已批量归档 '+selected.length+' 项。')}
function showArchives(){S.page='overview';S.showArchived=true;S.filter='all';S.themeFilter='全部';closeModal();render();save()}
function editTheme(id){sheet('这件事归到哪个主题',`<label for="topicselect">已有主题</label><select id="topicselect" class="topic-select">${S.topics.map(n=>`<option ${item(id).theme===n?'selected':''} value="${esc(n)}">${esc(n)}</option>`).join('')}</select><label for="newtopic">或者新建一个主题</label><input id="newtopic" class="modal-input" placeholder="例如：新家装修" maxlength="16"><button class="primary wide" onclick="saveTheme('${id}')">保存主题</button>`)}
function saveTheme(id){const n=document.getElementById('newtopic').value.trim()||document.getElementById('topicselect').value;if(!n)return;item(id).theme=n;if(!S.topics.includes(n))S.topics.push(n);save();render();detail(id)}
function statusHelp(){sheet('状态只回答：现在要我做什么？',`${Object.entries(STATUS).map(([k,v])=>`<div class="settingsrow">${badge({status:k})}<span class="small muted">${k==='paused'?'AI 在管 · 暂缓，可恢复':k==='error'?'该你了 · 需要处理异常':k==='wait_user'?'该你了 · 补充、决定或本人参与':terminal(k)?'已了结 · 先进入待归档':'AI 在管 · 我继续准备和推进'}</span></div>`).join('')}<p class="small muted">等回电、等物流、监控中，只作为“运行中”的说明。小人图标代表本人参与，与是否需要作决定分开。</p>`)}
function dsh(id){sheet('完整执行详情 · dsh',`<p>这里接回原有 dsh 任务页，不重复设计执行界面。</p><p class="small muted">目前没有提供 dsh 地址或任务映射，跳转尚未接通。</p><h3>本任务产出</h3>${attachmentRows(entity(id).parent||id)||'<p class="small muted">暂无产出附件。</p>'}`)}
function settings(){sheet('懂你，也按你的节奏来',`<h3>小包的口味</h3><p class="small muted">豆角丝、西蓝花、河粉、土豆丝、红烧肉；菜品需确认免辣。</p><button class="settingsrow" onclick="S.quiet=!S.quiet;save();settings()"><span>轻打扰模式</span><span>${S.quiet?'已开启':'已关闭'}</span></button><p class="small muted">一般进展放简报，紧急决定与到点事项再提醒。</p><h3 style="margin-top:18px">界面风格</h3><div class="control-row">${[['warm','温馨日常'],['business','沉静商务'],['play','奶油童趣']].map(([k,l])=>`<button onclick="S.visual='${k}';save();applyTheme();settings()">${S.visual===k?'✓ ':''}${l}</button>`).join('')}</div><button class="settingsrow" onclick="connections()">账号与权限 <span>未连接 ↗</span></button><button class="settingsrow" onclick="demoSettings()">演示时间与测试场景 <span>↗</span></button>`)}
function connections(){sheet('账号与权限',`<p class="small muted">本原型未连接盒马、京东、小红书、邮箱或办公账号。</p><div class="source">可先准备：检索思路、候选清单、菜单、报告草稿。</div><div class="source">需你确认：下单、订票、打电话、预约、发消息。</div><p class="small muted">正式接入时再展示权限范围、访问记录与撤销入口。</p>`)}
function advanceTime(hours){S.demoTime=new Date(now().getTime()+hours*3600000).toISOString();S.wallStart=Date.now();reconcile();save();closeModal();render();toast('演示时间已快进 '+hours+' 小时。')}
function resetAsk(){sheet('重置演示数据？',`<p class="muted">清除这一版浏览器内的演示对话、上传附件和任务状态，恢复初始样例。</p><button class="primary wide" onclick="S=seed();initRevision();save();closeModal();render()">确认重置</button>`)}
function sendInput(){const text=(document.getElementById('input')?.value||input).trim();if(!text)return;processInput(text,inputContext);input='';inputContext='';render();document.getElementById('main').scrollTop=999999}
function chooseFile(id=''){inputContext=id||detailID;document.getElementById('fileinput').click()}
document.getElementById('fileinput').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){toast('演示附件限 2MB，请选择更小的文件。');e.target.value='';return}const parent=inputContext||'notebook';const reader=new FileReader();reader.onload=()=>{const id='upload_'+Date.now();S.files.push({id,parent,name:f.name,type:f.type||'application/octet-stream',source:'uploaded',data:reader.result});receipt(entity(parent),'附件已关联到「'+entity(parent).title+'」，原始需求区可查看。','补充附件','上传附件：'+f.name);save();closeModal();go('home');document.getElementById('main').scrollTop=999999};reader.onerror=()=>toast('附件读取失败，请重试。');reader.readAsDataURL(f);e.target.value=''});
function openVoice(id=''){voiceContext=id||detailID||visibleContext();voiceOpen=true;mountVoice()}
function visibleContext(){const m=document.getElementById('main'),r=m.getBoundingClientRect();for(const el of m.querySelectorAll('[data-task]')){const b=el.getBoundingClientRect();if(b.top>=r.top&&b.top<r.top+r.height*.7)return el.dataset.task}return ''}
function mountVoice(){document.querySelector('.app').style.setProperty('--voice-bottom',S.page==='home'?'148px':'76px');document.getElementById('floating').innerHTML=voiceOpen?`<section class="voice-panel" role="region" aria-label="随时跟小天说"><div class="row between"><span class="small muted">${mic?'正在听，可以继续滑动':voiceContext&&entity(voiceContext)?'关于 · '+esc(entity(voiceContext).title):'看到什么，都可以跟我说'}</span><button onclick="closeVoice()" aria-label="收起输入" style="font-size:23px">×</button></div><textarea id="voiceinput" placeholder="补充一句，或直接说给我听…" oninput="voiceText=this.value">${esc(voiceText)}</textarea><div class="row between"><button class="record ${mic?'on':''}" onclick="record()">${icon('mic')}${mic?'停止录音':'语音输入'}</button><button class="primary" onclick="sendVoice()">发送 ↗</button></div></section>`:`<button class="floating-voice" onclick="openVoice()" aria-label="全局语音输入">${icon('mic')}</button>`}
function record(){if(mic){recognition?.stop();return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('可使用手机键盘语音，或直接输入。');document.getElementById('voiceinput').focus();return}recognition=new SR();recognition.lang='zh-CN';recognition.continuous=true;recognition.interimResults=true;const base=voiceText;recognition.onresult=e=>{let t='';for(let i=0;i<e.results.length;i++)t+=e.results[i][0].transcript;voiceText=base+t;const field=document.getElementById('voiceinput');if(field)field.value=voiceText};recognition.onend=()=>{mic=false;mountVoice()};recognition.onerror=()=>{mic=false;mountVoice();toast('语音识别不可用，可以直接输入。')};try{recognition.start();mic=true;mountVoice()}catch{toast('麦克风暂不可用，请直接输入。')}}
function closeVoice(){recognition?.stop();mic=false;voiceOpen=false;mountVoice()}
function sendVoice(){const text=(document.getElementById('voiceinput')?.value||voiceText).trim();if(!text)return;const y=document.getElementById('main').scrollTop;processInput(text,voiceContext);voiceText='';closeVoice();closeModal();render();document.getElementById('main').scrollTop=S.page==='home'?999999:y;toast('补充已记到对应任务，可以继续浏览。')}
function sheet(title,body){priorFocus=document.activeElement;document.getElementById('modal').innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="handle"></div><div class="sheetheader"><h3>${esc(title)}</h3><button class="close" onclick="closeModal()" aria-label="关闭">×</button></div>${body}</section></div>`;document.querySelector('.sheet .close')?.focus()}
function closeModal(){document.getElementById('modal').innerHTML='';detailID='';if(priorFocus?.isConnected)priorFocus.focus()}
function toast(text){document.getElementById('toast').innerHTML=`<div class="toast">${esc(text)}</div>`;setTimeout(()=>document.getElementById('toast').innerHTML='',3200)}
function go(page){S.page=page;if(page==='overview'){S.showArchived=false;S.timelineScroll=null;S.calendarZoomed=false;}closeModal();render();document.getElementById('main').scrollTop=0;save()}
function applyTheme(){const v=S.visual==='business'?['#f3f5f8','#293b52','#476180','#e7edf4']:S.visual==='play'?['#fbf6ed','#594537','#a07559','#f2e9d9']:['#f7f7f2','#263e36','#466b50','#eaf0e6'];['--bg','--ink','--green','--soft'].forEach((k,i)=>document.documentElement.style.setProperty(k,v[i]))}
function render(){reconcile();document.getElementById('brandicon').innerHTML=icon('spark');document.getElementById('main').innerHTML=S.page==='overview'?overview():home();document.getElementById('footer').innerHTML=`${S.page==='home'?`<div class="composer"><button class="iconbtn" onclick="chooseFile()" aria-label="添加附件">${icon('plus')}</button><textarea id="input" rows="1" placeholder="有事，直接跟我说…" oninput="input=this.value" onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendInput()}">${esc(input)}</textarea><button class="send" onclick="sendInput()" aria-label="发送">${icon('arrow')}</button></div>`:''}<nav class="nav"><button class="${S.page==='home'?'active':''}" onclick="go('home')">${icon('chat')}对话</button><button class="${S.page==='overview'?'active':''}" onclick="go('overview')">${icon('report')}总览</button></nav>`;applyTheme();mountVoice()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(voiceOpen)closeVoice();else closeModal()}if(e.key==='Tab'&&document.querySelector('.sheet')){const els=[...document.querySelectorAll('.sheet button,.sheet input,.sheet select,.sheet a,.voice-panel button,.voice-panel textarea,.floating-voice')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
initRevision();render();save();setInterval(()=>{if(reconcile()&&!voiceOpen&&!document.querySelector('.sheet')){const y=document.getElementById('main').scrollTop;render();document.getElementById('main').scrollTop=y}},60000);

function editDue(id){const t=entity(id);let value=t.due?new Date(ts(t.due)+8*3600000).toISOString().slice(0,16):'';sheet('调整需用时间',`<input class="modal-input" id="dueinput" type="datetime-local" value="${value}"><p class="small muted">留空代表时间尚未明确；实例时间不会改动其他任务。</p><button class="primary wide" onclick="saveDue('${id}')">保存时间</button>`)}
function saveDue(id){const t=entity(id),v=document.getElementById('dueinput').value;t.due=v||null;if(t.person&&!terminal(t.status)&&t.status!=='paused'){t.status=v&&ts(v)<=now().getTime()?'wait_user':'todo';t.waitSince=t.status==='wait_user'?v:null;}save();render();detail(id)}

function receipt(t,text,action='更新',inputText=''){const p=parentOf(t);S.messages.push({kind:'task_receipt',id:t.id,input:inputText,text,action,at:now().toISOString(),snapshot:{id:t.id,title:t.title,theme:p.theme,kind:p.kind,subtype:p.subtype,person:t.person,source:p.source,created:p.created,status:t.status,plan:action==='创建'?(t.plan||'先整理资料，再执行与汇报。'):(['完成','暂停','取消','异常'].includes(action)?(t.result||t.summary):t.summary||t.plan),summary:t.summary,quote:p.quote}})}
function compactCard(t){return `<button class="receipt-card" data-task="${t.id}" onclick="detail('${t.id}')"><div class="row between"><span class="receipt-meta">${esc(t.theme||parentOf(t).theme)} · ${t.kind==='continuing'?'周期 / 持续':'一次性'}</span>${badge(t)}</div><h3>${esc(t.title)}</h3><p>${esc(t.plan||t.summary||'整理需求，准备方案，执行后向你汇报。')}</p></button>`}
function initRevision(){if(S.layoutVersion===6)return;S.layoutVersion=6;for(const t of S.items){t.plan=t.steps?.map(s=>s.title).slice(0,4).join('，')||'整理需求、确认必要信息、准备方案、持续跟进。';t.confirmations=t.confirmations||[];if(terminal(t.status))t.result=t.summary;if(['error','paused','cancelled'].includes(t.status))t.result=t.summary}const t=item('shop');t.title='给小包买菜';t.theme='家庭购物';if(!S.topics.includes('家庭购物'))S.topics.push('家庭购物');t.plan='整理常购清单，核对优惠，产品加购，由您确认支付。';t.quote='家里牛奶跟小包吃的菜没有了。请参考我在盒马的历史订单，优先挑选常买的 4.0 鲜牛奶和有机蔬菜，搭配几天能吃的分量；有满减优惠帮我核对并用上。把商品加入购物车后告诉我，我再登录 App 确认订单和支付。请不要直接下单付款。';t.stage=t.status==='done'?3:0;if(!['done','cancelled','paused','error'].includes(t.status))t.status='running';if(t.stage===0){t.result='';t.summary='已了解常购偏好，正在核对优惠；随后加购并提醒您支付。'}t.steps=shoppingSteps(t.stage);if(t.stage===3)t.result='根据您的历史购物习惯，已加购 4.0 有机鲜牛奶、有机生菜等 5 件商品，共计 105 元（已使用满减优惠）。请您登录 App，确认下单支付。';if(!S.files.some(f=>f.id==='input_shopping'))S.files.push({id:'input_shopping',parent:'shop',name:'家庭购物偏好（演示）.pdf',type:'application/pdf',source:'uploaded',url:'assets/shopping-brief.pdf'});if(t.stage===3)addCartFile();if(!item('pdf_sample')){S.items.push({id:'pdf_sample',title:'整理本周项目报告',theme:'工作研究',kind:'oneoff',status:'done',created:'2026-10-13T10:00',quote:'请把本周项目进展整理成一份 PDF。先概述已完成的工作，再说明后续计划，让我能快速转发和回看。',plan:'整理素材，撰写结论，排版导出 PDF。',summary:'项目报告示例已整理，PDF 可直接预览和下载。',result:'已整理本周项目报告，包含结论、已完成事项和后续计划。PDF 已附在下方。',archive:'pending',source:'user',steps:[{title:'整理素材',status:'done',summary:'已归纳需求设计、交互调整和后续验证事项。',at:'10/13 10:00',end:'10/13 10:08'},{title:'撰写报告并导出 PDF',status:'done',summary:'已生成报告示例，文件可预览或下载。',at:'10/13 10:08',end:'10/13 10:20'}],confirmations:[]});S.files.push({id:'output_pdf',parent:'pdf_sample',name:'本周项目报告（演示）.pdf',type:'application/pdf',source:'generated',url:'assets/weekly-report.pdf'})}S.messages=S.messages.map(m=>{const x=entity(m.id||(m.ids||[])[0]);return x?{...m,kind:'task_receipt',id:x.id,action:m.kind==='result'?'完成':'更新',snapshot:{...x,theme:parentOf(x).theme}}:m});const creation={...t,status:'running',summary:t.plan};S.initialReceipt={...creation};if(!S.messages.some(m=>m.id==='pdf_sample'))receipt(item('pdf_sample'),'报告整理好了，PDF 放在结果里，可以直接预览。','完成');save()}
function shoppingSteps(stage){return [{title:'参考常购清单',status:'done',summary:'了解到您常买 4.0 鲜牛奶和各类有机蔬菜，已据此整理候选。',at:'10/14 09:00',end:'10/14 09:02'},{title:'核对优惠',status:stage>=1?'done':'running',summary:stage>=1?'已匹配满减优惠，预计 5 件商品合计 105 元。':'对照商品规格与满减门槛，计算实际到手价。',at:'10/14 09:02',end:stage>=1?'10/14 09:04':null,eta:'约 2 分钟'},{title:'加入购物车',status:stage>=2?'done':stage===1?'running':'todo',summary:stage>=2?'已模拟加入有机鲜奶、有机生菜等 5 件商品，未付款。':'按已核对的方案加入购物车，不提交订单。',at:stage>=1?'10/14 09:04':null,end:stage>=2?'10/14 09:05':null,eta:'约 1 分钟'},{title:'提醒您确认支付',status:stage===3?'done':stage===2?'running':'todo',summary:stage===3?'已整理购物车结果并提醒您登录 App 下单支付。':'将商品、优惠和金额汇总告知您，由您决定下单支付。',at:stage>=2?'10/14 09:05':null,end:stage===3?'10/14 09:06':null,eta:'加购后立即提醒'}]}
function addCartFile(){if(!S.files.some(f=>f.id==='cart_image'))S.files.push({id:'cart_image',parent:'shop',name:'购物车加购情况（模拟）.svg',type:'image/svg+xml',source:'generated',url:'assets/cart-preview.svg'})}
function home(){return `<div class="user-msg">家里牛奶和小包吃的菜没有了，参考常买的帮我加购，优惠帮我用上。</div>${assistant('<p>收到，已为你建好「给小包买菜」。我先整理常购清单、核对优惠，加购后待您下单支付。</p>'+compactCard(S.initialReceipt||item('shop')))}<div class="user-msg">你可以同时帮我处理别的事吗？</div>${assistant('<p>可以，这件事会继续推进。你直接说下一件就好，有进展我再回来告诉你。</p>')}${S.messages.map(m=>{if(m.kind==='task_receipt'){const t=m.snapshot||entity(m.id);return `${m.input?`<div class="user-msg">${esc(m.input)}</div>`:''}${assistant(`${m.action==='完成'?requestQuote(t):''}<div class="receipt-caption">${esc(m.action||'更新')} · ${fmt(m.at)}</div><p>${esc(m.text)}</p>${compactCard(t)}`)}`}return `${m.input?`<div class="user-msg">${esc(m.input)}</div>`:''}${assistant(`<p>${esc(m.text)}</p>${(m.ids||[]).map(id=>entity(id)?compactCard(entity(id)):'').join('')}`)}`}).join('')}<div class="quick-examples"><button onclick="openTextComposer('你好')">试试直接聊天</button><button onclick="detail('shop')">查看买菜任务</button></div><p class="notice">任务和进展为演示 · 不会真实加购、下单或付款</p>`}
function originalBlock(t){const p=parentOf(t),long=p.quote.length>90;return `<section class="detail-section request-block"><div class="section-kicker">原始需求</div><div class="request-time">${fmt(p.created)} · 您的交代</div>${long?`<details class="request-fold"><summary>${esc(p.quote.slice(0,78))}… <span>展开原文</span></summary><p>${esc(p.quote)}</p></details>`:`<p>${esc(p.quote)}</p>`}${fileRows(p.id,'uploaded')}${(p.updates||[]).length?`<details class="request-updates"><summary>后续补充 · ${p.updates.length} 条</summary>${p.updates.map(u=>`<p>${esc(u.text)}<small>${fmt(u.at)}</small></p>`).join('')}</details>`:''}</section>`}
function fileRows(id,source){return S.files.filter(f=>f.parent===id&&f.source===source).map(f=>`<button class="file-chip" onclick="previewFile('${f.id}')"><span class="file-glyph ${f.type==='application/pdf'?'pdf':''}">${f.type==='application/pdf'?'PDF':f.type.startsWith('image/')?'IMG':'DOC'}</span><span class="grow">${esc(f.name)}</span><span>↗</span></button>`).join('')}
function planTable(t){const steps=t.parent?[{title:t.title,status:t.status,summary:t.person?'您本人参与，小天负责提醒和准备。':'执行本次安排，结束后汇报结果。',at:t.due?fmt(t.due):null,eta:'待实际执行估计'}]:t.steps||[];return `<section class="detail-section"><h3>规划与执行</h3><div class="symbol-legend"><span>✓ 已完成</span><span>— 进行中</span><span>○ 待开始</span></div><div class="plan-table" role="table" aria-label="任务规划与执行">${steps.map(s=>{const sign=s.status==='done'?'✓':['running','wait_user','error','paused'].includes(s.status)?'—':'○';return `<div class="plan-row" role="row"><span class="plan-symbol ${s.status==='done'?'checked':sign==='—'?'working':''}" role="cell" aria-label="${sign==='✓'?'已完成':sign==='—'?'进行中':'待开始'}">${sign}</span><div role="cell"><strong>${esc(s.title)}</strong><p>${esc(s.summary||'')}</p><div class="plan-times">${s.at&&s.at!=='尚未开始'?`开始 ${esc(s.at)}`:'开始时间待安排'}${s.status==='done'?` · 结束 ${esc(s.end||s.eta||s.at||'已记录')}`:s.eta?` · 预计 ${esc(s.eta)}`:''}</div></div></div>`}).join('')||'<div class="empty-plan">我已接下需求，正在整理执行步骤。</div>'}</div></section>`}
function confirmations(t){const qs=t.confirmations||[];return `<section class="detail-section"><h3>用户待确认的信息</h3>${qs.length?qs.map(q=>`<div class="confirmation-entry"><p>${esc(q.question)}</p><small>提出于 ${fmt(q.at)}</small>${q.answer?`<div class="confirmation-answer">您的答复：${esc(q.answer)}<small>${fmt(q.answeredAt)}</small></div>`:`<div class="confirmation-options">${(q.options||['已确认','稍后再说']).map((o,i)=>`<button onclick="answerConfirmation('${t.id}','${q.id}',${i})">${esc(o)}</button>`).join('')}</div>`}</div>`).join(''):'<p class="none-value">无</p>'}</section>`}
function resultBlock(t){const has=t.status==='done'||['error','paused','cancelled'].includes(t.status);return `<section class="detail-section"><h3>任务结果</h3>${has?`<div class="result-box ${t.status}"><p>${esc(t.result||describe(t))}</p>${t.closeReason==='auto'?'<small>按规则自动关闭，实际完成未核实。</small>':''}</div>${t.status==='done'?fileRows(t.id,'generated'):''}${t.status==='done'&&t.id==='shop'&&S.files.some(f=>f.id==='cart_image')?'<button class="cart-preview" onclick="previewFile(\'cart_image\')"><img src="assets/cart-preview.svg" alt="模拟购物车：5 件商品，优惠后共计 105 元"><span>查看购物车图片 ↗</span></button>':''}`:'<div class="result-empty" aria-label="任务尚未完成，结果区域暂为空"></div>'}</section>`}
function detail(id){detailID=id;const t=entity(id);if(!t)return;const p=parentOf(t);sheet(t.title,`<div class="detail-taskmeta"><span>${esc(p.theme)} · ${t.kind==='continuing'?'延续性':t.parent?'本次实例':'一次性'}</span>${badge(t)}</div>${originalBlock(t)}${planTable(t)}${confirmations(t)}${resultBlock(t)}<button class="full-execution" onclick="dsh('${id}')">查看完整任务执行详情 <span>↗</span></button><div class="final-controls">${t.status==='paused'?`<button onclick="resume('${id}')">恢复任务</button>`:!terminal(t.status)?`<button onclick="pause('${id}')">暂停任务</button>`:`<button disabled>暂停任务</button>`}<button ${terminal(t.status)?'disabled':''} onclick="cancelAsk('${id}')">取消任务</button><button class="supplement" onclick="openVoice('${id}')">补充信息</button></div><details class="taskmore"><summary>更多任务设置</summary><div class="control-row"><button onclick="editTheme('${p.id}')">修改主题</button><button onclick="chooseFile('${p.id}')">补充附件</button>${terminal(t.status)?`<button onclick="reopen('${id}')">重新打开</button>`:''}${t.person&&t.status==='wait_user'?`<button onclick="markDone('${id}')">本人事项已完成</button>`:''}${t.id==='shop'&&t.status==='running'?'<button onclick="advanceShopping()">演示推进下一步</button>':''}</div></details><p class="notice">模拟进展 · dsh 尚未连接 · 所有支付由您完成</p>`)}
function completion(t,reason='user'){t.status='done';t.archive='pending';t.finished=now().toISOString();t.closeReason=reason;t.summary=reason==='auto'?'已按两天规则自动关闭，本人是否实际完成尚未核实。':t.person?'已记录您确认完成，结果保留待归档。':'已完成任务目标，结果与附件已整理。';t.result=t.summary;if(t.steps)t.steps=t.steps.map(s=>({...s,status:'done',end:s.end||fmt(now().toISOString())}));receipt(t,reason==='auto'?'任务已按规则自动关闭，实际完成未核实，记录已保留。':'这件事已完成，结果已放进任务概览。','完成');if(t.parent)ensureNext(t.parent)}
function advanceShopping(){const t=item('shop');if(t.status!=='running'||t.stage>=3)return;t.stage=(t.stage||0)+1;t.steps=shoppingSteps(t.stage);t.summary=t.stage===1?'优惠已核对，正在按方案加购。':t.stage===2?'5 件商品已加购，正在整理结果并提醒您支付。':'已加购 5 件商品，共计 105 元；请您登录 App 下单支付。';if(t.stage===3){t.status='done';t.archive='pending';t.finished=now().toISOString();t.result='根据您的历史购物习惯，已加购 4.0 有机鲜牛奶、有机生菜、西蓝花、土豆和胡萝卜等 5 件商品，共计 105 元（已使用满减优惠）。请您登录 App，确认下单支付。';addCartFile();t.confirmations.push({id:'payment_handoff',question:'加购已经完成，后续由您登录购物 App 下单支付；可在完成后回告我。',at:now().toISOString(),blocking:false,options:['我已下单支付','暂时不下单']});receipt(t,'商品已加购，5 件共 105 元（已使用满减）。请您登录 App 确认下单支付，购物车图片已放入结果。','完成')}save();refreshPreserving()}
function askMissing(){const t=item('shop');if(terminal(t.status))return toast('先重新打开或重置买菜演示。');if(t.confirmations.some(q=>q.id==='milk_choice'&&!q.answer))return;t.status='wait_user';t.confirmations.push({id:'milk_choice',question:'常买规格暂缺货，是否换为同品牌 4.0 有机鲜奶 950mL？',at:now().toISOString(),blocking:true,options:['可以，换同品牌','不换，先不买牛奶']});receipt(t,'核对商品时遇到缺货，需要您决定是否换同品牌规格；其他任务继续推进。','需要确认');save();refreshPreserving()}
function answerConfirmation(id,qid,i){const t=entity(id),q=(t.confirmations||[]).find(x=>x.id===qid);if(!q||q.answer)return;q.answer=q.options[i];q.answeredAt=now().toISOString();if(q.blocking&&t.status==='wait_user'){t.status='running';t.summary='已收到您的选择，继续按确认方案推进。'}receipt(t,'收到您的确认：“'+q.answer+'”。'+(q.blocking?'我继续处理这件事。':'AI 加购任务已完成，此回复记入确认记录。'),'确认更新');save();refreshPreserving()}
function pause(id){const t=entity(id);if(terminal(t.status)||t.status==='paused')return;t.beforePause=t.status;t.status='paused';t.result='任务已暂停。已完成的步骤和记录保留，后续步骤暂不执行，恢复后继续。';if(!t.parent)S.instances.filter(x=>x.parent===id&&!terminal(x.status)).forEach(x=>{x.beforePause=x.status;x.status='paused'});receipt(t,'已暂停「'+t.title+'」，已有结果会保留，需要时可以恢复。','暂停');save();refreshPreserving()}
function resume(id){const t=entity(id);if(t.status!=='paused')return;t.status=t.beforePause||'running';t.result='';if(!t.parent)S.instances.filter(x=>x.parent===id&&x.status==='paused').forEach(x=>x.status=x.beforePause||'todo');receipt(t,'已恢复「'+t.title+'」，我从暂停前的进度继续。','恢复');save();refreshPreserving()}
function cancelTask(id){const t=entity(id);t.status='cancelled';t.archive='pending';t.result='已按您的要求取消任务，后续步骤不再执行。已有记录与附件仍保留。';if(!t.parent)S.instances.filter(x=>x.parent===id&&!terminal(x.status)).forEach(x=>{x.status='cancelled';x.archive='pending'});receipt(t,'已取消「'+t.title+'」，记录保留，之后可以一起归档。','取消');save();closeModal();render()}
function recoverDemo(id){const t=entity(id);t.status='running';t.result='';t.summary='已演示恢复连接，继续处理原任务。';receipt(t,'连接恢复已模拟，我继续推进「'+t.title+'」。','恢复');save();refreshPreserving()}
function refreshPreserving(){const y=document.getElementById('main').scrollTop,id=detailID,open=!!document.querySelector('.plan-table');const batches=new Map([...document.querySelectorAll('.batch-bundle')].map(el=>[el.dataset.batch,{open:el.open,y:el.querySelector('.batch-grid').scrollTop}]));render();document.querySelectorAll('.batch-bundle').forEach(el=>{const b=batches.get(el.dataset.batch);if(b){el.open=b.open;el.querySelector('.batch-grid').scrollTop=b.y;}});document.getElementById('main').scrollTop=y;if(open&&id)detail(id)}
function processInput(text,context=''){if((/^(你好|谢谢|好的|辛苦了)[！!。\s]*$/.test(text)||/你能做什么|可以同时|什么是语义缓存|1\s*\+\s*1/.test(text))){const answer=/谢谢|辛苦/.test(text)?'不客气，你继续忙。有进展我会回来告诉你。':/语义缓存/.test(text)?'语义缓存是按问题的含义复用已有答案，而不只匹配完全相同的文字。':/1\s*\+\s*1/.test(text)?'1 + 1 = 2。':'可以直接聊天，也可以交代买菜、整理报告、查资料等任务。任务在后台推进，你不用等这一件结束。';S.messages.push({kind:'direct',input:text,text:answer,at:now().toISOString()});save();return []}let ids=[];const rules=[[/奶奶|接站|南站|免辣|餐厅|充电/,'pickup'],[/牛奶|补货|蔬菜|买菜/,'shop'],[/菜单|食谱/,'menu'],[/蒸烤箱|蹲价/,'oven'],[/晨报|dsh|AI 项目/i,'research'],[/身高|体重/,'growth'],[/会议室|规划讨论/,'meeting'],[/疫苗/,'vaccine'],[/邮箱|校招/,'notes']];ids=rules.filter(([r])=>r.test(text)).map(([,id])=>id);if(!ids.length&&context&&entity(context))ids=[context];let created=false;if(!ids.length){if(!/帮|请|提醒|整理|生成|预约|买|查|写|安排|监控/.test(text)&&/[?？]|怎么|什么|为什么/.test(text)){S.messages.push({kind:'direct',input:text,text:'这是即时问答演示，我先直接回应，不创建任务。如果需要我持续查找或整理结果，可以继续交代。',at:now().toISOString()});save();return []}created=true;const id='new_'+Date.now()+'_'+Math.random().toString(36).slice(2,8);S.items.push({id,title:text.slice(0,23)+(text.length>23?'…':''),theme:/工作|报告|PDF/i.test(text)?'工作研究':'生活照料',quote:text,kind:/每天|每周|监控/.test(text)?'continuing':'oneoff',subtype:'周期',status:'running',person:false,source:'user',created:now().toISOString(),summary:'已接下需求，正在整理资料与执行步骤。',plan:'明确目标，整理资料，完成执行，再向您汇报。',steps:[{title:'整理需求与资料',status:'running',summary:'核对目标和现有资料，准备后续执行。',at:fmt(now().toISOString()),eta:'信息齐全后估计'},{title:'执行并汇总结果',status:'todo',summary:'完成目标后，将结论和附件放入任务结果。',eta:'待规划'}],confirmations:[],result:''});ids=[id]}for(const id of ids){const t=entity(id);t.updates=[...(t.updates||[]),{text,at:now().toISOString()}];if(!created&&!terminal(t.status))t.summary='新补充已记录，继续核对并推进原有任务。';receipt(t,created?'收到，已为您建好「'+t.title+'」。我先整理资料和步骤，完成后回来汇报。':'已将补充更新到「'+t.title+'」，不用重新交代，后续继续按这张任务卡跟进。',created?'创建':'补充',text)}save();return ids}
function previewFile(id){const f=S.files.find(x=>x.id===id);if(!f)return;const url=f.url||f.data;sheet(f.name,`${f.type==='application/pdf'&&url?`<object class="pdf-frame" data="${url}" type="application/pdf"><p>当前浏览器不支持内嵌 PDF，请点下方链接查看。</p></object><a class="pdf-open" href="${url}" target="_blank" rel="noopener">打开 PDF 查看 ↗</a>`:f.body?`<pre class="preview-text">${esc(f.body)}</pre>`:f.type.startsWith('image/')&&url?`<img class="attachment-preview" src="${url}" alt="${esc(f.name)}">`:'<p class="muted">附件已关联，可下载查看。</p>'}<button class="primary wide" onclick="downloadFile('${id}')">下载附件 ↓</button><p class="notice">演示附件不包含真实订单或个人资料。</p>`)}
function downloadFile(id){const f=S.files.find(x=>x.id===id),a=document.createElement('a');const u=f.url||f.data||URL.createObjectURL(new Blob([f.body],{type:'text/plain;charset=utf-8'}));a.href=u;a.download=f.name;a.click();if(!f.url&&!f.data)setTimeout(()=>URL.revokeObjectURL(u),1000)}
function demoSettings(){sheet('体验任务在后台推进',`<p class="small muted">买菜任务接收后立即运行，你可以继续聊天。以下按钮用于快速查看各个阶段。</p><div class="control-row"><button onclick="advanceShopping()">买菜：推进下一步</button><button onclick="askMissing()">演示：需要确认规格</button></div><div class="control-row"><button onclick="demoShoppingException()">演示：加购异常</button><button onclick="advanceTime(48)">时间快进 2 天</button></div><p class="small muted">任务完成、需要确认、暂停、取消和补充后，对话里会新增更新卡。历史卡保留当时状态，点开看到最新详情。</p><button class="settingsrow" onclick="resetAsk()">重新开始演示 <span>↗</span></button>`)}
function demoShoppingException(){const t=item('shop');if(terminal(t.status))return toast('请先重置买菜任务演示。');t.status='error';t.result='加购未完成：演示购物服务暂时不可用。已完成的清单与优惠核对保留；请稍后重试。';receipt(t,'加购遇到异常，已有清单保留。我把原因和下一步放入了任务结果。','异常');save();refreshPreserving()}

setInterval(()=>{const t=item('shop');if(t&&t.status==='running'&&(t.stage||0)<3)advanceShopping()},20000);

function requestQuote(t){const text=String(t?.quote||'').replace(/\s+/g,' ').trim();if(!text)return '';const chars=Array.from(text),snippet=chars.length>28?chars.slice(0,27).join('')+'…':text;return `<blockquote class="refquote"><span class="refquote-label">您的吩咐</span><span class="refquote-text">${esc(snippet)}</span></blockquote>`;}
